Checked Syntax
// Statement block form
checked
{
    int a = int.MaxValue;
    int b = a + 1;  // Throws OverflowException
}
// Expression form
int x = checked(int.MaxValue + 1); // Throws OverflowException

Example: Wıthout Checked
int a = int.MaxValue;
int b = a + 1; 
Console.WriteLine(b); // Output: -2147483648 (wraps around, 
                                              no exception)

Example: Wıth Checked
try
{
    int a = int.MaxValue;
    int b = checked(a + 1); 
    Console.WriteLine(b);
}
catch (OverflowException ex)
{
    Console.WriteLine("Overflow detected!");
}

BigInteger (Cont’d)
using System;
using System.Numerics;
class Program
{
    static void Main()
    { 
        BigInteger a = BigInteger.Parse("12345678901234567890");
        BigInteger b = BigInteger.Pow(10, 30);   // 10^30
        BigInteger sum = a + b;
        Console.WriteLine($"a = {a}"); // a = 12345678901234567890
        Console.WriteLine($"b = {b}"); // b = 1000000000000000000000000000000
        Console.WriteLine($"a + b = {sum}");  // a + b = 10000123456789012345678901234567890
    } 
}

